        for period in range(1, h + 1):
            pattern = {}
            valid = True
            for r, value in known.items():
                k = r % period
                if k in pattern and pattern[k] != value:
                    valid = False
                    break
                pattern[k] = value
            if valid and len(pattern) == period:
                return [[pattern[r % period]] * w for r in range(h)]

    # Find a periodic diagonal color sequence. The source diagonals may slope
    # down-right (c-r) or down-left (c+r).
    candidates = []
    for sign in (-1, 1):  # offset = c-r, c+r
        offsets = {}
        for r in range(h):
            for c in range(w):
                value = grid[r][c]
                if value:
                    offset = c + sign * r
                    offsets.setdefault(offset, set()).add(value)
        for period in range(1, min(h, w) + 1):
            pattern = {}
            valid = True
            for offset, values in offsets.items():
                if len(values) != 1:
                    valid = False
                    break
                value = next(iter(values))
                k = offset % period
                if k in pattern and pattern[k] != value:
                    valid = False
                    break
                pattern[k] = value
            if valid and len(pattern) == period:
                candidates.append((period, sign, pattern))
                break
    if not candidates:
        raise ValueError("Could not infer a complete periodic pattern")
    period, sign, pattern = min(candidates, key=lambda item: item[0])
    return [[pattern[(c + sign * r) % period] for c in range(w)] for r in range(h)]
'''
